import { useMemo } from 'react';

export interface KpiDrillDownDataView {
  loading: boolean;
  error: Error | null;
  isEmpty: boolean;
  skipped?: boolean;
}

export interface UseKpiDrillDownFullPageEmptyStateParams {
  enabled: boolean;
  views: KpiDrillDownDataView[];
}

export const useKpiDrillDownFullPageEmptyState = ({
  enabled,
  views,
}: UseKpiDrillDownFullPageEmptyStateParams): boolean => {
  const activeViews = useMemo(
    () => views.filter((view) => !view.skipped),
    [views],
  );

  return useMemo(() => {
    if (!enabled) {
      return false;
    }

    if (activeViews.length === 0) {
      return false;
    }

    if (activeViews.some((view) => view.loading)) {
      return false;
    }

    if (activeViews.some((view) => view.error)) {
      return false;
    }

    return activeViews.every((view) => view.isEmpty);
  }, [activeViews, enabled]);
};
